    F = b*c**(sympy.S(5)/3)*d**4*log(c**(sympy.S(2)/3)*x**2 + 1)/(2*c**2*d**6 + 2*e**6) - b*c**(sympy.S(5)/3)*e*(d**3*sqrt(-c**2) - e**3)*log(c**(sympy.S(2)/3)*x + (-c**2)**(sympy.S(1)/6))/(2*(-c**2)**(sympy.S(2)/3)*(c**2*d**6 + e**6)) + b*c**(sympy.S(5)/3)*e*(d**3*sqrt(-c**2) - e**3)*log(c**(sympy.S(4)/3)*x**2 - c**(sympy.S(2)/3)*x*(-c**2)**(sympy.S(1)/6) + (-c**2)**(sympy.S(1)/3))/(4*(-c**2)**(sympy.S(2)/3)*(c**2*d**6 + e**6)) - sqrt(3)*b*c**(sympy.S(5)/3)*e*(d**3*sqrt(-c**2) - e**3)*atan(sqrt(3)*(c**(sympy.S(4)/3) + 2*x*(-c**2)**(sympy.S(5)/6))/(3*c**(sympy.S(4)/3)))/(2*(-c**2)**(sympy.S(2)/3)*(c**2*d**6 + e**6)) + b*c**(sympy.S(5)/3)*e*(d**3*sqrt(-c**2) + e**3)*log(-c**(sympy.S(2)/3)*x + (-c**2)**(sympy.S(1)/6))/(2*(-c**2)**(sympy.S(2)/3)*(c**2*d**6 + e**6)) - b*c**(sympy.S(5)/3)*e*(d**3*sqrt(-c**2) + e**3)*log(c**(sympy.S(4)/3)*x**2 + c**(sympy.S(2)/3)*x*(-c**2)**(sympy.S(1)/6) + (-c**2)**(sympy.S(1)/3))/(4*(-c**2)**(sympy.S(2)/3)*(c**2*d**6 + e**6)) + sqrt(3)*b*c**(sympy.S(5)/3)*e*(d**3*sqrt(-c**2) + e**3)*atan(sqrt(3)*(2*c**(sympy.S(2)/3)*x/(-c**2)**(sympy.S(1)/6) + 1)/3)/(2*(-c**2)**(sympy.S(2)/3)*(c**2*d**6 + e**6)) - b*c**(sympy.S(2)/3)*d*e**3*atan(c**(sympy.S(1)/3)*x)/(c**2*d**6 + e**6) - b*c**(sympy.S(2)/3)*d*(c*d**3 - sqrt(3)*e**3)*log(c**(sympy.S(2)/3)*x**2 - sqrt(3)*c**(sympy.S(1)/3)*x + 1)/(4*c**2*d**6 + 4*e**6) - b*c**(sympy.S(2)/3)*d*(c*d**3 + sqrt(3)*e**3)*log(c**(sympy.S(2)/3)*x**2 + sqrt(3)*c**(sympy.S(1)/3)*x + 1)/(4*c**2*d**6 + 4*e**6) + b*c**(sympy.S(2)/3)*d*(sqrt(3)*c*d**3 - e**3)*atan(2*c**(sympy.S(1)/3)*x + sqrt(3))/(2*c**2*d**6 + 2*e**6) - b*c**(sympy.S(2)/3)*d*(sqrt(3)*c*d**3 + e**3)*atan(2*c**(sympy.S(1)/3)*x - sqrt(3))/(2*c**2*d**6 + 2*e**6) + b*c**2*d**5*atan(c*x**3)/(e*(c**2*d**6 + e**6)) - b*c*d**2*e**2*log(c**2*x**6 + 1)/(2*c**2*d**6 + 2*e**6) + 3*b*c*d**2*e**2*log(d + e*x)/(c**2*d**6 + e**6) - (a + b*atan(c*x**3))/(e*(d + e*x))
    assert integrate(f, x) == F

